import { auth } from '@/lib/firebase/client-init';
import { apiClient } from '@/lib/api-client';
import type { LoginCredentials, SignupCredentials, UserProfile } from '@/lib/types';
import {
  GoogleAuthProvider,
  getAdditionalUserInfo,
  sendPasswordResetEmail,
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
  type UserCredential
} from "firebase/auth";
import { fetchUserProfileApi } from './userService';

// Re-export for convenience
export { fetchUserProfileApi };


// --- Authentication Functions ---

/**
 * Login with email and password
 * Uses Firebase client SDK for authentication, then syncs with backend
 */
export async function loginWithEmail(credentials: LoginCredentials): Promise<UserCredential> {
  try {
    const userCredential = await signInWithEmailAndPassword(
      auth,
      credentials.email,
      credentials.password
    );

    // Backend session is created via the API client interceptor (auth token)
    return userCredential;
  } catch (error: any) {
    if (
      error.code === "auth/invalid-credential" ||
      error.code === "auth/user-not-found" ||
      error.code === "auth/wrong-password" ||
      error.code === "auth/invalid-email"
    ) {
      throw new Error("Invalid email or password.");
    }
    throw new Error(error.message || "Login failed. Please try again.");
  }
}

/**
 * Login with Google
 * Uses Firebase client SDK for authentication
 */
export async function loginWithGoogle(): Promise<{user: UserCredential['user'], isNewUser: boolean}> {
  const provider = new GoogleAuthProvider();
  try {
    const result = await signInWithPopup(auth, provider);
    const info = getAdditionalUserInfo(result);

    // If new user, create profile on backend
    if (info?.isNewUser) {
      await apiClient.post('/auth/signup', {
        email: result.user.email,
        displayName: result.user.displayName,
      });
    }

    return { user: result.user, isNewUser: !!info?.isNewUser };
  } catch (error: any) {
    throw new Error(error.message || "Google Sign-In failed.");
  }
}

/**
 * Logout user
 * Signs out from Firebase and revokes backend session
 */
export async function serviceLogoutUser() {
  try {
    // Revoke backend session first
    await apiClient.post('/auth/logout');
  } catch (error) {
    console.error('Backend logout error:', error);
  }

  // Always sign out from Firebase
  await signOut(auth);
}

/**
 * Signs up a new user via the backend API
 * This creates both Firebase auth and Firestore profile
 */
export async function serviceSignupUser(credentials: SignupCredentials) {
  return apiClient.post<{ success: boolean; user: any }>('/auth/signup', credentials);
}

/**
 * Send password reset email
 */
export async function forgotPasswordService(email: string) {
  return sendPasswordResetEmail(auth, email);
}

/**
 * Get current session from backend
 */
export async function getCurrentSession() {
  return apiClient.get<{ success: boolean; user: any }>('/auth/session');
}

/**
 * Creates or updates a user profile document via backend
 */
export async function createOrUpdateUserProfileApi(userId: string, data: Partial<UserProfile>): Promise<UserProfile> {
  const response = await apiClient.put<{ success: boolean; user: UserProfile }>(`/users/${userId}`, data);
  return response.user;
}"}

