import { apiClient } from '@/lib/api-client';

/**
 * Flow execution result
 */
export interface FlowExecutionResult {
  success: boolean;
  output?: any;
  error?: string;
  metadata?: {
    executionTime?: number;
    tokensUsed?: number;
    [key: string]: any;
  };
}

/**
 * Flow execution request
 */
export interface FlowExecutionRequest {
  flowName: string;
  payload: Record<string, any>;
  enableTracing?: boolean;
}

/**
 * Flow test request
 */
export interface FlowTestRequest {
  flowConfig: any;
  payload: Record<string, any>;
}

/**
 * Flow Service
 * Handles dynamic flow execution via backend
 */
export const flowService = {
  /**
   * Execute a dynamic flow
   */
  async executeFlow(request: FlowExecutionRequest): Promise<FlowExecutionResult> {
    return apiClient.post<FlowExecutionResult>('/flows/execute', request);
  },

  /**
   * Test a flow configuration
   */
  async testFlow(request: FlowTestRequest): Promise<{ success: boolean; message: string }> {
    return apiClient.post<{ success: boolean; message: string }>('/flows/test', request);
  },
};

/**
 * Execute a flow by name with payload
 */
export async function executeFlowApi(flowName: string, payload: Record<string, any>, enableTracing = true): Promise<FlowExecutionResult> {
  return flowService.executeFlow({ flowName, payload, enableTracing });
}

/**
 * Test a flow configuration
