  const { user } = useAuth();
  const [state, setState] = useState<RetrievalState>({
    isRetrieving: false,
    error: null,
    context: null,
    sources: [],
  });

  const retrieveContext = async (
    query: string,
    projectId?: string,
    options: {
      topK?: number;
      minScore?: number;
    } = {}
  ) => {
    if (!user) {
      setState(prev => ({ ...prev, error: 'User not authenticated' }));
      return null;
    }

    setState({
      isRetrieving: true,
      error: null,
      context: null,
      sources: [],
    });

    try {
      const results = await ragService.retrieveContext(query, options.topK || 5);

      // Filter by minScore if provided
      const filteredResults = options.minScore 
        ? results.filter(r => r.score >= options.minScore!)
        : results;

      // Combine results into context
      const context = filteredResults.map(r => r.content).join('\n\n');

      // Map to sources format
      const sources = filteredResults.map(r => ({
        content: r.content,
        score: r.score,
        sourceFile: r.metadata?.title,
        type: r.metadata?.type || 'unknown',
      }));

      setState({
        isRetrieving: false,
        error: null,
        context,
        sources,
      });

      return context;
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Unknown error';
      setState({
        isRetrieving: false,
        error: errorMessage,
        context: null,
        sources: [],
      });
      return null;
    }
  };"}

