{"file_path": "arkan-frontend/src/lib/cache-config.ts", "initial_content": "/**
 * Cache configuration for React Query
 * Optimizes data fetching and reduces unnecessary requests
 */

export const CACHE_CONFIG = {
  // Default stale time - data is fresh for 5 minutes
  staleTime: 1000 * 60 * 5,

  // Cache time - data stays in cache for 10 minutes
  cacheTime: 1000 * 60 * 10,

  // Retry failed requests
  retry: 1,

  // Refetch on window focus for real-time data
  refetchOnWindowFocus: false,

  // Refetch on reconnect
  refetchOnReconnect: true,
};

// Specific cache configs for different data types
export const CACHE_KEYS = {
  projects: {
    all: ['projects'] as const,
    detail: (id: string) => ['projects', id] as const,
    staleTime: 1000 * 60 * 5, // 5 minutes
  },

  users: {
    profile: (id: string) => ['users', id] as const,
    credits: ['users', 'credits'] as const,
    staleTime: 1000 * 60 * 10, // 10 minutes
  },

  agents: {
    all: ['agents'] as const,
    detail: (id: string) => ['agents', id] as const,
    categories: ['agents', 'categories'] as const,
    staleTime: 1000 * 60 * 15, // 15 minutes (agents rarely change)
  },

  templates: {
    report: ['templates', 'report'] as const,
    presentation: ['templates', 'presentation'] as const,
    staleTime: 1000 * 60 * 30, // 30 minutes (templates rarely change)
  },
};
"}

