/**
 * Register Service Worker for offline support
 */
export function ServiceWorkerRegister() {
  useEffect(() => {
    if (
      typeof window !== 'undefined' &&
      'serviceWorker' in navigator &&
      process.env.NODE_ENV === 'production'
    ) {
      window.addEventListener('load', () => {
        navigator.serviceWorker
          .register('/sw.js')
          .then((registration) => {
            console.log('✅ Service Worker registered:', registration);
          })
          .catch((error) => {
            console.error('❌ Service Worker registration failed:', error);
          });
      });
    }
  }, []);

  return null;
}
"}

{"file_path": "arkan-frontend/src/components/optimized/memoized-card.tsx", "initial_content": "import { memo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

/**
 * Memoized Card component - prevents unnecessary re-renders
 * Use for list items that don't change frequently
 */
interface MemoizedCardProps {
  title: string;
  description?: string;
  children?: React.ReactNode;
  onClick?: () => void;
}

export const MemoizedCard = memo(function MemoizedCard({
  title,
  description,
  children,
  onClick,
}: MemoizedCardProps) {
  return (
    <Card 
      className="hover:shadow-lg transition-shadow cursor-pointer"
      onClick={onClick}
    >
      <CardHeader>
        <CardTitle>{title}</CardTitle>
        {description && (
          <p className="text-sm text-muted-foreground">{description}</p>
        )}
      </CardHeader>
      {children && <CardContent>{children}</CardContent>}
    </Card>
  );
}, (prevProps, nextProps) => {
  // Custom comparison - only re-render if these props change
  return (
    prevProps.title === nextProps.title &&
    prevProps.description === nextProps.description &&
    prevProps.children === nextProps.children
  );
});
"}

