// Response interceptor for error handling
axiosInstance.interceptors.response.use(
  (response) => response,
  (error: AxiosError) => {
    if (error.response?.status === 401) {
      // Unauthorized - redirect to login
      if (typeof window !== 'undefined') {
        window.location.href = '/login';
      }
    }
    return Promise.reject(error);
  }
);

// Generic API client with caching support
export const apiClient = {
  async get<T>(url: string, params?: any, options?: { cache?: boolean; ttl?: number }): Promise<T> {
    const cacheKey = `get:${url}:${JSON.stringify(params || {})}`;

    // Check cache if enabled
    if (options?.cache !== false) {
      const cached = apiCache.get<T>(cacheKey);
      if (cached) {
        return cached;
      }
    }

    const response = await axiosInstance.get(url, { params });

    // Cache response if enabled
    if (options?.cache !== false) {
      apiCache.set(cacheKey, response.data, options?.ttl);
    }

    return response.data;
  },

  async post<T>(url: string, data?: any, config?: AxiosRequestConfig): Promise<T> {
    const response = await axiosInstance.post(url, data, config);

    // Invalidate related caches on POST
    if (url.includes('projects')) {
      apiCache.invalidatePattern('projects:');
    }
    if (url.includes('agents')) {
      apiCache.invalidatePattern('agents:');
    }

    return response.data;
  },

  async put<T>(url: string, data?: any): Promise<T> {
    const response = await axiosInstance.put(url, data);

    // Invalidate related caches on PUT
    if (url.includes('projects')) {
      apiCache.invalidatePattern('projects:');
    }
    if (url.includes('users')) {
      apiCache.invalidatePattern('users:');
    }

    return response.data;
  },

  async delete<T>(url: string): Promise<T> {
    const response = await axiosInstance.delete(url);

    // Invalidate related caches on DELETE
    if (url.includes('projects')) {
      apiCache.invalidatePattern('projects:');
    }
    if (url.includes('agents')) {
      apiCache.invalidatePattern('agents:');
    }

    return response.data;
  },

  async patch<T>(url: string, data?: any): Promise<T> {
    const response = await axiosInstance.patch(url, data);
    return response.data;
