import { apiClient as baseApiClient } from './api-client';
import { apiCache, cacheKeys } from './api-cache';

/**
 * Cached API client with automatic cache management
 */
export const apiClientCached = {
  /**
   * GET request with optional caching
   */
  async get<T>(
    url: string, 
    params?: any, 
    options?: { cache?: boolean; ttl?: number }
  ): Promise<T> {
    const cacheKey = `get:${url}:${JSON.stringify(params || {})}`;

    // Check cache if enabled
    if (options?.cache !== false) {
      const cached = apiCache.get<T>(cacheKey);
      if (cached) {
        console.log('✅ Cache hit:', cacheKey);
        return cached;
      }
    }

    // Fetch from API
    const data = await baseApiClient.get<T>(url, params);

    // Cache response if enabled
    if (options?.cache !== false) {
      apiCache.set(cacheKey, data, options?.ttl);
      console.log('💾 Cached:', cacheKey);
    }

    return data;
  },

  /**
   * POST request with cache invalidation
   */
  async post<T>(url: string, data?: any, config?: any): Promise<T> {
    const result = await baseApiClient.post<T>(url, data, config);

    // Invalidate related caches
    this._invalidateRelatedCaches(url);

    return result;
  },

  /**
   * PUT request with cache invalidation
   */
  async put<T>(url: string, data?: any): Promise<T> {
    const result = await baseApiClient.put<T>(url, data);

    // Invalidate related caches
    this._invalidateRelatedCaches(url);

    return result;
  },

  /**
   * DELETE request with cache invalidation
   */
  async delete<T>(url: string): Promise<T> {
    const result = await baseApiClient.delete<T>(url);

    // Invalidate related caches
    this._invalidateRelatedCaches(url);

    return result;
  },

  /**
   * PATCH request
   */
  async patch<T>(url: string, data?: any): Promise<T> {
    return baseApiClient.patch<T>(url, data);
  },

  /**
   * Manual cache control
   */
  cache: {
    invalidate: (key: string) => apiCache.invalidate(key),
    invalidatePattern: (pattern: string) => apiCache.invalidatePattern(pattern),
    clear: () => apiCache.clear(),
    stats: () => apiCache.getStats(),
  },

  /**
   * Private: Invalidate caches based on URL pattern
   */
  _invalidateRelatedCaches(url: string) {
    if (url.includes('projects')) {
      apiCache.invalidatePattern('get:/projects');
      console.log('🗑️ Invalidated projects cache');
    }
    if (url.includes('agents')) {
      apiCache.invalidatePattern('get:/agents');
      console.log('🗑️ Invalidated agents cache');
    }
    if (url.includes('users')) {
      apiCache.invalidatePattern('get:/users');
      console.log('🗑️ Invalidated users cache');
    }
  },
};
