              )}
            </Button>
            <Button 
              onClick={handleSave} 
              disabled={updateMutation.isPending || !hasChanges}
            >
              {updateMutation.isPending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                  Saving...
                </>
              ) : (
