{"file_path": "arkan-backend/src/websocket/socket.ts", "initial_content": "/**
 * WebSocket Server Configuration
 * Provides real-time updates for frontend clients
 */

import { Server as HTTPServer } from 'http';
import { Server, Socket } from 'socket.io';
import { adminAuth } from '../config/firebase';

// WebSocket events
export enum SocketEvents {
  // Connection
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',
  ERROR = 'error',

  // Authentication
  AUTHENTICATE = 'authenticate',
  AUTHENTICATED = 'authenticated',
  AUTH_ERROR = 'auth_error',

  // Project updates
  PROJECT_CREATED = 'project:created',
  PROJECT_UPDATED = 'project:updated',
  PROJECT_DELETED = 'project:deleted',

  // User updates
  USER_UPDATED = 'user:updated',
  USER_STATUS = 'user:status',

  // Notifications
  NOTIFICATION = 'notification',

  // Typing indicators
  TYPING_START = 'typing:start',
  TYPING_STOP = 'typing:stop',
}

// Socket user data
interface SocketUser {
  uid: string;
  email?: string;
  role?: string;
}

// Extend Socket with user data
interface AuthenticatedSocket extends Socket {
  user?: SocketUser;
}

export class WebSocketServer {
  private io: Server;
  private authenticatedSockets = new Map<string, SocketUser>();

  constructor(httpServer: HTTPServer) {
    this.io = new Server(httpServer, {
      cors: {
        origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
        credentials: true,
      },
      transports: ['websocket', 'polling'],
    });

    this.setupMiddleware();
    this.setupEventHandlers();
  }

  /**
   * Setup authentication middleware
   */
  private setupMiddleware() {
    this.io.use(async (socket: AuthenticatedSocket, next) => {
      try {
        const token = socket.handshake.auth.token || socket.handshake.headers.authorization?.split(' ')[1];

        if (!token) {
          return next(new Error('Authentication token missing'));
        }

        // Verify token with Firebase Admin
        const decodedToken = await adminAuth.verifyIdToken(token);

        // Attach user data to socket
        socket.user = {
          uid: decodedToken.uid,
          email: decodedToken.email,
          role: decodedToken.role || 'user',
        };

        // Store authenticated socket
        this.authenticatedSockets.set(socket.id, socket.user);

        next();
      } catch (error) {
        console.error('Socket authentication error:', error);
        next(new Error('Authentication failed'));
      }
    });
  }

  /**
   * Setup event handlers
   */
  private setupEventHandlers() {
    this.io.on(SocketEvents.CONNECT, (socket: AuthenticatedSocket) => {
      console.log(`✅ Client connected: ${socket.id} (${socket.user?.email})`);

      // Join user-specific room
      if (socket.user) {
        socket.join(`user:${socket.user.uid}`);

        // Emit authenticated event
        socket.emit(SocketEvents.AUTHENTICATED, {
          userId: socket.user.uid,
          email: socket.user.email,
        });
      }

      // Handle disconnect
      socket.on(SocketEvents.DISCONNECT, () => {
        console.log(`❌ Client disconnected: ${socket.id}`);
        this.authenticatedSockets.delete(socket.id);
      });

      // Handle typing indicators
      socket.on(SocketEvents.TYPING_START, (data) => {
        socket.broadcast.emit(SocketEvents.TYPING_START, {
          userId: socket.user?.uid,
          ...data,
        });
      });

      socket.on(SocketEvents.TYPING_STOP, (data) => {
        socket.broadcast.emit(SocketEvents.TYPING_STOP, {
          userId: socket.user?.uid,
          ...data,
        });
      });
    });
  }

  /**
   * Emit project created event to user
   */
  emitProjectCreated(userId: string, project: any) {
    this.io.to(`user:${userId}`).emit(SocketEvents.PROJECT_CREATED, project);
  }

  /**
   * Emit project updated event to user
   */
  emitProjectUpdated(userId: string, project: any) {
    this.io.to(`user:${userId}`).emit(SocketEvents.PROJECT_UPDATED, project);
  }

  /**
   * Emit project deleted event to user
   */
  emitProjectDeleted(userId: string, projectId: string) {
    this.io.to(`user:${userId}`).emit(SocketEvents.PROJECT_DELETED, { projectId });
  }

  /**
   * Emit user updated event
   */
  emitUserUpdated(userId: string, user: any) {
    this.io.to(`user:${userId}`).emit(SocketEvents.USER_UPDATED, user);
  }

  /**
   * Emit notification to user
   */
  emitNotification(userId: string, notification: any) {
    this.io.to(`user:${userId}`).emit(SocketEvents.NOTIFICATION, notification);
  }

  /**
   * Emit notification to all users
   */
  emitBroadcastNotification(notification: any) {
    this.io.emit(SocketEvents.NOTIFICATION, notification);
  }

  /**
   * Get connected users count
   */
  getConnectedUsersCount(): number {
    return this.authenticatedSockets.size;
  }

  /**
   * Check if user is connected
   */
  isUserConnected(userId: string): boolean {
    const sockets = Array.from(this.authenticatedSockets.values());
    return sockets.some(user => user.uid === userId);
  }

  /**
   * Get Socket.IO instance
   */
  getIO(): Server {
    return this.io;
  }
}

// Singleton instance
let wsServer: WebSocketServer | null = null;

export function initializeWebSocket(httpServer: HTTPServer): WebSocketServer {
  if (!wsServer) {
    wsServer = new WebSocketServer(httpServer);
    console.log('🔌 WebSocket server initialized');
  }
  return wsServer;
}

export function getWebSocketServer(): WebSocketServer | null {
  return wsServer;
}
"}

