{"file_path": "arkan-frontend/src/lib/websocket-client.ts", "initial_content": "/**
 * WebSocket Client
 * Handles real-time communication with backend
 */

import { io, Socket } from 'socket.io-client';
import { auth } from './firebase/client-init';

// WebSocket events (must match backend)
export enum SocketEvents {
  // Connection
  CONNECT = 'connect',
  DISCONNECT = 'disconnect',
  ERROR = 'error',

  // Authentication
  AUTHENTICATE = 'authenticate',
  AUTHENTICATED = 'authenticated',
  AUTH_ERROR = 'auth_error',

  // Project updates
  PROJECT_CREATED = 'project:created',
  PROJECT_UPDATED = 'project:updated',
  PROJECT_DELETED = 'project:deleted',

  // User updates
  USER_UPDATED = 'user:updated',
  USER_STATUS = 'user:status',

  // Notifications
  NOTIFICATION = 'notification',

  // Typing indicators
  TYPING_START = 'typing:start',
  TYPING_STOP = 'typing:stop',
}

export type SocketEventCallback = (data: any) => void;

class WebSocketClient {
  private socket: Socket | null = null;
  private reconnectAttempts = 0;
  private maxReconnectAttempts = 5;
  private eventListeners = new Map<string, Set<SocketEventCallback>>();
  private isAuthenticated = false;

  /**
   * Connect to WebSocket server
   */
  async connect(): Promise<void> {
    if (this.socket?.connected) {
      console.log('✅ WebSocket already connected');
      return;
    }

    try {
      // Get Firebase auth token
      const currentUser = auth.currentUser;
      if (!currentUser) {
        console.warn('⚠️ Cannot connect WebSocket: User not authenticated');
        return;
      }

      const token = await currentUser.getIdToken();

      // Create socket connection
      const socketUrl = process.env.NEXT_PUBLIC_API_URL?.replace('/api/v1', '') || 'http://localhost:4000';

      this.socket = io(socketUrl, {
        auth: { token },
        transports: ['websocket', 'polling'],
        reconnection: true,
        reconnectionDelay: 1000,
        reconnectionDelayMax: 5000,
        reconnectionAttempts: this.maxReconnectAttempts,
      });

      this.setupEventHandlers();
      console.log('🔌 WebSocket connecting...');
    } catch (error) {
      console.error('❌ WebSocket connection error:', error);
      throw error;
    }
  }

  /**
   * Setup event handlers
   */
  private setupEventHandlers() {
    if (!this.socket) return;

    // Connection events
    this.socket.on(SocketEvents.CONNECT, () => {
      console.log('✅ WebSocket connected');
      this.reconnectAttempts = 0;
    });

    this.socket.on(SocketEvents.AUTHENTICATED, (data) => {
      console.log('✅ WebSocket authenticated:', data);
      this.isAuthenticated = true;
    });

    this.socket.on(SocketEvents.DISCONNECT, (reason) => {
      console.log('❌ WebSocket disconnected:', reason);
      this.isAuthenticated = false;
    });

    this.socket.on(SocketEvents.ERROR, (error) => {
      console.error('❌ WebSocket error:', error);
    });

    this.socket.on(SocketEvents.AUTH_ERROR, (error) => {
      console.error('❌ WebSocket auth error:', error);
      this.disconnect();
    });

    // Reconnection events
    this.socket.io.on('reconnect_attempt', (attempt) => {
      this.reconnectAttempts = attempt;
      console.log(`🔄 WebSocket reconnect attempt ${attempt}/${this.maxReconnectAttempts}`);
    });

    this.socket.io.on('reconnect', () => {
      console.log('✅ WebSocket reconnected');
      this.reconnectAttempts = 0;
    });

    this.socket.io.on('reconnect_failed', () => {
      console.error('❌ WebSocket reconnection failed');
    });
  }

  /**
   * Disconnect from WebSocket server
   */
  disconnect() {
    if (this.socket) {
      console.log('🔌 WebSocket disconnecting...');
      this.socket.disconnect();
      this.socket = null;
      this.isAuthenticated = false;
    }
  }

  /**
   * Subscribe to an event
   */
  on(event: SocketEvents | string, callback: SocketEventCallback) {
    if (!this.socket) {
      console.warn('⚠️ WebSocket not connected. Call connect() first.');
      return;
    }

    // Store callback for unsubscribe
    if (!this.eventListeners.has(event)) {
      this.eventListeners.set(event, new Set());
    }
    this.eventListeners.get(event)!.add(callback);

    // Register with socket
    this.socket.on(event, callback);
  }

  /**
   * Unsubscribe from an event
   */
  off(event: SocketEvents | string, callback?: SocketEventCallback) {
    if (!this.socket) return;

    if (callback) {
      // Remove specific callback
      this.socket.off(event, callback);
      this.eventListeners.get(event)?.delete(callback);
    } else {
      // Remove all callbacks for this event
      this.socket.off(event);
      this.eventListeners.delete(event);
    }
  }

  /**
   * Emit an event to server
   */
  emit(event: SocketEvents | string, data?: any) {
    if (!this.socket?.connected) {
      console.warn('⚠️ WebSocket not connected. Cannot emit event:', event);
      return;
    }

    this.socket.emit(event, data);
  }

  /**
   * Check if connected
   */
  isConnected(): boolean {
    return this.socket?.connected || false;
  }

  /**
   * Check if authenticated
   */
  isAuth(): boolean {
    return this.isAuthenticated;
  }

  /**
   * Get socket instance
   */
  getSocket(): Socket | null {
    return this.socket;
  }
}

// Singleton instance
export const wsClient = new WebSocketClient();

// Auto-connect when user is authenticated
if (typeof window !== 'undefined') {
  auth.onAuthStateChanged((user) => {
    if (user) {
      // Connect when user logs in
      wsClient.connect().catch(console.error);
    } else {
      // Disconnect when user logs out
      wsClient.disconnect();
    }
  });
}

export default wsClient;
"}

{"file_path": "arkan-frontend/src/hooks/use-websocket.ts", "initial_content": "/**
 * WebSocket React Hooks
 * Provides easy-to-use hooks for WebSocket functionality
 */

import { useEffect, useState, useCallback } from 'react';
import { useQueryClient } from '@tantml:invoke>react-query';
import { wsClient, SocketEvents, type SocketEventCallback } from '@/lib/websocket-client';
import { projectKeys } from '@/lib/query-keys';

/**
 * Hook for WebSocket connection status
 */
export function useWebSocketConnection() {
  const [isConnected, setIsConnected] = useState(wsClient.isConnected());
  const [isAuthenticated, setIsAuthenticated] = useState(wsClient.isAuth());

  useEffect(() => {
    const checkConnection = () => {
      setIsConnected(wsClient.isConnected());
      setIsAuthenticated(wsClient.isAuth());
    };

    // Check initially
    checkConnection();

    // Setup listeners
    wsClient.on(SocketEvents.CONNECT, checkConnection);
    wsClient.on(SocketEvents.AUTHENTICATED, checkConnection);
    wsClient.on(SocketEvents.DISCONNECT, checkConnection);

    // Check every 5 seconds
    const interval = setInterval(checkConnection, 5000);

    return () => {
      clearInterval(interval);
      wsClient.off(SocketEvents.CONNECT, checkConnection);
      wsClient.off(SocketEvents.AUTHENTICATED, checkConnection);
      wsClient.off(SocketEvents.DISCONNECT, checkConnection);
    };
  }, []);

  const connect = useCallback(() => {
    return wsClient.connect();
  }, []);

  const disconnect = useCallback(() => {
    wsClient.disconnect();
  }, []);

  return {
    isConnected,
    isAuthenticated,
    connect,
    disconnect,
  };
}

/**
 * Hook for listening to WebSocket events
 */
export function useWebSocketEvent(
  event: SocketEvents | string,
  callback: SocketEventCallback,
  dependencies: any[] = []
) {
  useEffect(() => {
    wsClient.on(event, callback);

    return () => {
      wsClient.off(event, callback);
    };
  }, [event, ...dependencies]);
}

/**
 * Hook for real-time project updates
 * Automatically invalidates React Query cache when projects change
 */
export function useWebSocketProjects() {
  const queryClient = useQueryClient();

  useWebSocketEvent(SocketEvents.PROJECT_CREATED, (project) => {
    console.log('📥 Project created:', project);
    queryClient.invalidateQueries({ queryKey: projectKeys.lists() });
  });

  useWebSocketEvent(SocketEvents.PROJECT_UPDATED, (project) => {
    console.log('📥 Project updated:', project);
    queryClient.invalidateQueries({ queryKey: projectKeys.lists() });
    queryClient.invalidateQueries({ queryKey: projectKeys.detail(project.id) });
  });

  useWebSocketEvent(SocketEvents.PROJECT_DELETED, ({ projectId }) => {
    console.log('📥 Project deleted:', projectId);
    queryClient.invalidateQueries({ queryKey: projectKeys.lists() });
    queryClient.removeQueries({ queryKey: projectKeys.detail(projectId) });
  });
}

/**
 * Hook for real-time notifications
 */
export function useWebSocketNotifications(
  onNotification: (notification: any) => void
) {
  useWebSocketEvent(SocketEvents.NOTIFICATION, onNotification, [onNotification]);
}

/**
 * Hook for typing indicators
 */
export function useTypingIndicator() {
  const [typingUsers, setTypingUsers] = useState<string[]>([]);

  useWebSocketEvent(SocketEvents.TYPING_START, ({ userId }) => {
    setTypingUsers(prev => [...new Set([...prev, userId])]);
  });

  useWebSocketEvent(SocketEvents.TYPING_STOP, ({ userId }) => {
    setTypingUsers(prev => prev.filter(id => id !== userId));
  });

  const startTyping = useCallback((data?: any) => {
    wsClient.emit(SocketEvents.TYPING_START, data);
  }, []);

  const stopTyping = useCallback((data?: any) => {
    wsClient.emit(SocketEvents.TYPING_STOP, data);
  }, []);

  return {
    typingUsers,
    startTyping,
    stopTyping,
  };
}

/**
 * Hook to emit WebSocket events
 */
export function useWebSocketEmit() {
  return useCallback((event: SocketEvents | string, data?: any) => {
    wsClient.emit(event, data);
  }, []);
}
"}

