import { useWebSocketConnection } from '@/hooks/use-websocket';
import { Wifi, WifiOff, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

/**
 * WebSocket Connection Status Indicator
 */
export function WebSocketStatus({ className }: { className?: string }) {
  const { isConnected, isAuthenticated } = useWebSocketConnection();

  if (!isAuthenticated && !isConnected) {
    return null; // Don't show if not attempting to connect
  }

  return (
    <div
      className={cn(
        'flex items-center gap-2 px-3 py-1.5 rounded-full text-xs font-medium transition-all',
        isConnected && isAuthenticated
          ? 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400'
          : isConnected
          ? 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400'
          : 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400',
        className
      )}
    >
      {isConnected && isAuthenticated ? (
        <>
          <Wifi className="h-3 w-3" />
          <span>Real-time</span>
        </>
      ) : isConnected ? (
        <>
          <Loader2 className="h-3 w-3 animate-spin" />
          <span>Connecting...</span>
        </>
      ) : (
        <>
          <WifiOff className="h-3 w-3" />
          <span>Offline</span>
        </>
      )}
    </div>
  );
}

/**
 * Simple connection indicator dot
 */
export function WebSocketDot({ className }: { className?: string }) {
  const { isConnected, isAuthenticated } = useWebSocketConnection();

  return (
    <div
      className={cn(
        'h-2 w-2 rounded-full transition-all',
        isConnected && isAuthenticated
          ? 'bg-green-500 animate-pulse'
          : isConnected
          ? 'bg-yellow-500 animate-pulse'
          : 'bg-red-500',
        className
      )}
      title={
        isConnected && isAuthenticated
          ? 'Connected (Real-time)'
          : isConnected
          ? 'Connecting...'
          : 'Disconnected'
      }
    />
  );
}
"}

