  11 /**
  12  * Parses a markdown string and converts it into a structured array of Chapter and Section objects.
  13  * This function is now more intelligent, handling hierarchy and preserving existing IDs and content.
  14  *
  15  * @param markdown The raw markdown string to parse.
  16  * @param existingContent The current project content to preserve IDs and properties.
  17  * @param isToc Only parse structure (headings, lists), ignore other content.
  18  * @returns An array of Chapter and Section objects.
  19  */
  20 export function parseMarkdownToContent(markdown: string, existingContent: ProjectContent, isToc: boolean = false): ProjectContent {
  21   const ast = unified().use(remarkParse).use(remarkGfm).parse(markdown) as MdastRoot;
  22   const newContent: (Chapter | Section)[] = [];
  23   let currentChapter: Chapter | null = null;
  24   let currentSection: Section | null = null;
  25   let accumulatedContent: RootContent[] = [];
  26 
  27   const findExistingSection = (title: string): Section | undefined => {
  28     for (const item of existingContent) {
  29       if (item instanceof Section && item.title === title) return item;
  30       if (item instanceof Chapter) {
  31         const found = item.sections.find(s => s.title === title);
  32         if (found) return found;
  33       }
  34     }
  35     return undefined;
  36   };
  37 
  38   const findExistingChapter = (title: string): Chapter | undefined => {
  39     return existingContent.find(item => item instanceof Chapter && item.title === title) as Chapter | undefined;
  40   };
  41 
  42   const flushSection = () => {
  43     if (currentSection) {
  44       const sectionMarkdown = isToc ? currentSection.content : unified().use(remarkGfm).use(remarkStringify).stringify({ type: 'root', children: accumulatedContent }).trim();
  45       
  46       // Only update content if it has changed and we are not in TOC mode
  47       if (sectionMarkdown !== currentSection.content) {
  48         currentSection = currentSection.with({ content: sectionMarkdown });
  49       }
  50 
  51       if (currentChapter) {
  52         const sectionIndex = currentChapter.sections.findIndex(s => s.id === currentSection!.id);
  53         if (sectionIndex !== -1) {
  54             currentChapter = currentChapter.updateSection(currentSection.id, () => currentSection!);
  55         } else {
  56             currentChapter = currentChapter.addSection(currentSection);
  57         }
  58       } else {
  59         const existingIndex = newContent.findIndex(item => item.id === currentSection!.id);
  60         if(existingIndex !== -1) {
  61           (newContent as (Chapter | Section)[])[existingIndex] = currentSection;
  62         } else {
  63           newContent.push(currentSection);
  64         }
  65       }
  66     }
  67     accumulatedContent = [];
  68   };
  69 
  70   const flushChapter = () => {
  71     flushSection();
  72     if (currentChapter) {
  73         const chapterIndex = newContent.findIndex(c => c.id === currentChapter!.id);
  74         if(chapterIndex !== -1) {
  75             (newContent as (Chapter | Section)[])[chapterIndex] = currentChapter;
  76         } else {
  77             newContent.push(currentChapter);
  78         }
  79     }
  80     currentChapter = null;
  81   };
  82 
  83   // Process all nodes in the AST
  84   for (const node of ast.children) {
  85     if (node.type === 'heading') {
  86       const title = getNodeText(node).trim();
  87       if (node.depth === 1) { // Chapter
  88         flushChapter();
  89         const existingChapter = findExistingChapter(title);
  90         currentChapter = new Chapter({ 
  91           id: existingChapter?.id, 
  92           title: title, 
  93           sections: existingChapter?.sections ? [...existingChapter.sections] : []
  94         });
  95         currentSection = null; // Reset section when a new chapter starts
  96       } else { // Section
  97         flushSection();
  98         const existingSection = findExistingSection(title);
  99         currentSection = new Section({
 100             id: existingSection?.id,
 101             title: title,
 102             type: existingSection?.type || 'report',
 103             content: existingSection?.content, // Preserve existing content
 104             controls: existingSection?.controls,
 105             prompt: existingSection?.prompt,
 106             rules: Array.isArray(existingSection?.rules) ? [...existingSection.rules] : [],
 107             guidelines: Array.isArray(existingSection?.guidelines) ? [...existingSection.guidelines] : [],
 108             constraints: Array.isArray(existingSection?.constraints) ? [...existingSection.constraints] : [],
 109             behaviors: Array.isArray(existingSection?.behaviors) ? [...existingSection.behaviors] : [],
 110             context: existingSection?.context,
 111         });
 112       }
 113     } else if (node.type === 'list' && currentChapter && isToc) {
 114         // Handle sections listed under a chapter
 115         for (const listItem of node.children) {
 116             if (listItem.type === 'listItem') {
 117                 const sectionTitle = getNodeText(listItem).trim();
 118                 flushSection();
 119                 const existingSection = findExistingSection(sectionTitle);
 120                 currentSection = new Section({
 121                     id: existingSection?.id,
 122                     title: sectionTitle,
 123                     type: existingSection?.type || 'report',
 124                     content: existingSection?.content,
 125                     controls: existingSection?.controls,
 126                     prompt: existingSection?.prompt,
 127                     rules: existingSection?.rules ? [...existingSection.rules] : [],
 128                     guidelines: existingSection?.guidelines ? [...existingSection.guidelines] : [],
 129                     constraints: existingSection?.constraints ? [...existingSection.constraints] : [],
 130                     behaviors: existingSection?.behaviors ? [...existingSection.behaviors] : [],
 131                     context: existingSection?.context,
 132                 });
 133                 flushSection(); // Immediately add the section
 134                 currentSection = null;
 135             }
 136         }
 137     } else {
 138       if (currentSection) {
 139         accumulatedContent.push(node);
 140       }
 141     }
 142   }
 143 
 144   flushChapter();
 145 
 146   return newContent;
 147 }
