 * AST Utility Functions
 * Helper functions for working with markdown AST nodes
 */

import type { RootContent } from 'mdast';

/**
 * Extract text content from an AST node
 */
export function getNodeText(node: RootContent): string {
  if (!node) return '';

  // Handle text nodes
  if (node.type === 'text') {
    return node.value;
  }

  // Handle nodes with children
  if ('children' in node && Array.isArray(node.children)) {
    return node.children.map(child => getNodeText(child as RootContent)).join('');
  }

  // Handle inline code
  if (node.type === 'inlineCode') {
    return node.value;
  }

  // Handle code blocks
  if (node.type === 'code') {
    return node.value;
  }

  return '';
}

/**
 * Check if node is a heading
 */
export function isHeading(node: RootContent): boolean {
  return node.type === 'heading';
}

/**
 * Check if node is a list
 */
export function isList(node: RootContent): boolean {
  return node.type === 'list';
}

/**
 * Check if node is a paragraph
 */
export function isParagraph(node: RootContent): boolean {
  return node.type === 'paragraph';
}
"}

